rule.example:
public class Example {
    void bad() {
        String name = "joke";                      // violation
        for (int i = 0; i < 3; i++) { }            // violation
        for (String s : names) { }                 // violation
    }

    void good() {
        var name = "joke";
        for (var i = 0; i < 3; i++) { }
        for (var s : names) { }

        int uninitialized;                         // no violation: var needs an initializer
        String nothing = null;                     // no violation: null has no type to infer
        int[] shorthand = {1, 2};                  // no violation: var forbids this form
        Runnable task = () -> { };                 // no violation: a lambda needs a target type
        Supplier<String> make = String::new;       // no violation: so does a method reference
        int a = 1, b = 2;                          // no violation: var forbids multiple declarators
    }
}

public class Example {
    private static int count;
    private static final Map<String, String> REGISTRY = new HashMap<>();

    static String format(int n) { return "" + n; }        // violation: a helper, not state
    static int get() { return count; }                    // violation: a read, not a write
    static void register(String k, String v) {            // violation: not a write to the field
        REGISTRY.put(k, v);
    }

    static void bump() { count++; }                       // no violation: writes private static state
    static void reset() { count = 0; }                    // no violation: so does this
    public static void main(String[] args) { }            // no violation: the JVM requires static

    String betterAsAnInstanceMethod(int n) { return "" + n; }
}

final class Utility {                                     // no instance methods, private constructor
    private Utility() { }

    static String format(int n) { return "" + n; }        // no violation: a utility class
}

@UtilityClass                                             // Lombok makes these static once compiled
public class Coercion {
    String render(int n) { return "" + n; }               // no violation: the marker is enough
}

public class Cost implements Comparable<Cost> {
    static Cost finite(int amount) { return new Cost(); }  // no violation: a named constructor
    static Comparable<Cost> comparable(int a) { … }        // no violation: a declared interface
    static Number total(int a) { … }                       // violation: a factory for something else
    static Cost[] all() { … }                              // violation: an array is not the constructor
}

public class Example {
    private boolean check() { return true; }        // violation
    protected boolean verify() { return true; }     // violation

    boolean inspect() { return true; }              // no violation: package-private
    public boolean isValid() { return true; }       // no violation: public API

    private Example() { }                           // no violation: constructors are out of scope

    @Override
    protected void finalize() { }                   // no violation: visibility is not chosen here

    @ApiStatus.OverrideOnly
    protected void hook() { }                       // no violation: a declared extension point

    @VisibleForTesting
    protected boolean seam() { return true; }       // no violation: a declared test seam

    @VisibleForTesting
    private boolean hidden() { return true; }       // violation: no marker makes private reachable

    @SuppressWarnings("PMD.AvoidPrivateAndProtectedMethods")
    protected void other() { }                      // no violation: the escape for anything else
}

public class Example {
    boolean check() { return true; }                     // violation: an unmarked seam

    @VisibleForTesting
    boolean verify() { return true; }                    // no violation

    public boolean isValid() { return true; }            // no violation: not package-private

    @Override
    void run() { }                                       // no violation: visibility is inherited

    @Test
    void reportsTheViolation() { }                       // no violation: a JUnit test method
}

public class Example {
    void bad(java.util.List<Item> items, Context context) {
        items.forEach(item -> {                     // violation
            validate(item, context);
            save(item, context);
        });
        map(x -> { return x + 1; });                // violation: converts to an expression
        map(x -> { save(x); });                     // violation: so does this
    }

    void good(java.util.List<Item> items, Context context) {
        items.forEach(item -> process(item, context));  // no violation: not a block
        items.forEach(this::save);                      // no violation: no body at all
        map(x -> x + 1);                                // no violation
        Runnable task = () -> { };                      // no violation: nothing to extract
        map(x -> x > 0 ? positive(x) : negative(x));    // no violation: expression bodies are out of scope
    }

    @VisibleForTesting
    void process(Item item, Context context) {
        validate(item, context);
        save(item, context);
    }
}

public class Example {
    Runnable bad() {
        return new Runnable() {                     // violation
            @Override
            public void run() {
                doTheWork();
            }
        };
    }

    Runnable good() {
        return new Worker();                        // no violation: a named class
    }

    Object typeCapture() {
        return new TypeToken<java.util.List<String>>() { };  // no violation: the body is the mechanism
    }

    static final class Worker implements Runnable {
        @Override
        public void run() {
            doTheWork();
        }
    }
}

enum Op {
    PLUS { int apply(int a, int b) { return a + b; } },      // no violation: an enum constant body
    MINUS { int apply(int a, int b) { return a - b; } };

    abstract int apply(int a, int b);
}

public class Example {
    void bad() {
        Mockito.doReturn(true);              // violation: import static …Mockito.doReturn
        Collections.unmodifiableList(xs);    // violation: self-describing, so not excluded
        Collectors.toList();                 // violation
        AccessType.WRITE.name();             // violation: fields count too
    }

    void good() {
        doReturn(true);                      // statically imported
        Math.max(a, b);                      // no violation: 3 characters, under the floor
        Optional.empty();                    // no violation: empty what?
        Duration.ofSeconds(3);               // no violation: of[A-Z] prefix
        Registry.INSTANCE.lookup();          // no violation: instance of what?
        List.copyOf(xs);                     // no violation: a copy of what, into what?
        Example.class.getName();             // no violation: a class literal cannot be imported
    }

    void conflicting(int[] a, Object x) {
        Arrays.toString(a);                  // no violation: two owners of `toString` in one file,
        Objects.toString(x);                 // so the developer chooses one, or neither
    }
}

public class Example {
    private java.util.List<String> bad;         // violation: add an import
    private java.time.Duration alsoBad;         // violation

    void m(java.util.Map.Entry<String, String> e) { }   // violation: nested type, either import works
}

import java.util.List;

public class Good {
    private List<String> names;                 // no violation
    private String text;                        // no violation: java.lang is already in scope

    void m(java.awt.List awtList) { }           // no violation: `List` is taken, so you choose
}
